package typescript

import (
	"encoding/hex"
	"encoding/json"
	"fmt"
	"sort"
	"strings"

	"openapi-sdkgen/internal/compiler/naming"
)

type typeRenderMode uint8

const (
	typeRenderModeLocal typeRenderMode = iota
	typeRenderModeContract
)

type typeRenderScope struct {
	mode               typeRenderMode
	componentReference func(name string, direction projection) string
}

var (
	typeRenderLocal    = typeRenderScope{mode: typeRenderModeLocal}
	typeRenderContract = typeRenderScope{mode: typeRenderModeContract}
)

func typeRenderModule(reference func(name string, direction projection) string) typeRenderScope {
	return typeRenderScope{mode: typeRenderModeLocal, componentReference: reference}
}

// typeExpression keeps local and cross-module renderings together so emitters
// never have to discover component references by rewriting rendered source.
type typeExpression struct {
	local    string
	contract string
}

func rawTypeExpression(source string) typeExpression {
	return typeExpression{local: source, contract: source}
}

func scopedTypeExpression(local, contract string) typeExpression {
	return typeExpression{local: local, contract: contract}
}

func componentProjectionTypeExpression(name string, direction projection) typeExpression {
	helper := "ComponentOutput"
	if direction == projectionInput {
		helper = "ComponentInput"
	}
	argument := quoteTS(name)
	local := helper + "<" + argument + ">"
	return scopedTypeExpression(local, "Contract."+local)
}

func (expression typeExpression) render(scope typeRenderScope) string {
	if scope.mode == typeRenderModeContract {
		return expression.contract
	}
	return expression.local
}

type identityClass string

const (
	identityExactPublic identityClass = "exact-public"
	identityResource    identityClass = "resource-convenience"
	identityPrivate     identityClass = "private"
)

// plannedIdentity separates an OpenAPI source identity from the private
// identifier used by generated implementation code.
type plannedIdentity struct {
	source            string
	class             identityClass
	privateIdentifier string
}

func planIdentity(class identityClass, role, source string) plannedIdentity {
	return plannedIdentity{
		source:            source,
		class:             class,
		privateIdentifier: stablePrivateIdentifier(role, source),
	}
}

func (identity plannedIdentity) typeKey() string {
	return quoteTS(identity.source)
}

func (identity plannedIdentity) bracket(base string) string {
	return base + "[" + quoteTS(identity.source) + "]"
}

func stablePrivateIdentifier(role, source string) string {
	if role == "operation-type" {
		return "__sdkgen_"
	}
	base, err := naming.Property(source)
	if err != nil || base == "" {
		base = "value"
	}
	// The suffix is a lossless encoding, not a truncated digest. Two distinct
	// role/source pairs therefore cannot produce the same private identifier.
	return "__sdkgen_" + base + "_r" + hex.EncodeToString([]byte(role)) + "_s" + hex.EncodeToString([]byte(source))
}

type runtimeProperty struct {
	key   string
	value string
}

// runtimeObjectExpression constructs externally keyed records through
// Object.fromEntries. Unlike a plain object literal, "__proto__" is installed
// as an ordinary enumerable own data property. The generated call is marked
// pure so bundlers can discard unused runtime concerns, including recursively
// rendered records passed as arguments.
func runtimeObjectExpression(properties []runtimeProperty) string {
	sorted := append([]runtimeProperty(nil), properties...)
	sort.SliceStable(sorted, func(left, right int) bool {
		return sorted[left].key < sorted[right].key
	})
	var output strings.Builder
	output.WriteString("/* @__PURE__ */ Object.fromEntries([")
	for index, property := range sorted {
		if index > 0 {
			output.WriteString(", ")
		}
		output.WriteByte('[')
		output.WriteString(quoteTS(property.key))
		output.WriteString(", ")
		output.WriteString(property.value)
		output.WriteByte(']')
	}
	output.WriteString("])")
	return output.String()
}

// runtimeJSONExpression renders JSON data as deterministic JavaScript source.
// Object members are sorted and recursively constructed without prototype
// setter semantics; array order remains the source order.
func runtimeJSONExpression(value any) (string, error) {
	switch typed := value.(type) {
	case map[string]any:
		properties := make([]runtimeProperty, 0, len(typed))
		for key, item := range typed {
			rendered, err := runtimeJSONExpression(item)
			if err != nil {
				return "", fmt.Errorf("JSON property %q: %w", key, err)
			}
			properties = append(properties, runtimeProperty{key: key, value: rendered})
		}
		return runtimeObjectExpression(properties), nil
	case map[string]map[string]any:
		properties := make([]runtimeProperty, 0, len(typed))
		for key, item := range typed {
			rendered, err := runtimeJSONExpression(item)
			if err != nil {
				return "", fmt.Errorf("JSON property %q: %w", key, err)
			}
			properties = append(properties, runtimeProperty{key: key, value: rendered})
		}
		return runtimeObjectExpression(properties), nil
	case []any:
		var output strings.Builder
		output.WriteByte('[')
		for index, item := range typed {
			rendered, err := runtimeJSONExpression(item)
			if err != nil {
				return "", fmt.Errorf("JSON item %d: %w", index, err)
			}
			if index > 0 {
				output.WriteString(", ")
			}
			output.WriteString(rendered)
		}
		output.WriteByte(']')
		return output.String(), nil
	default:
		data, err := json.Marshal(value)
		if err != nil {
			return "", fmt.Errorf("marshal JSON literal: %w", err)
		}
		return string(data), nil
	}
}

func readonlyJSONType(value any) (string, error) {
	switch typed := value.(type) {
	case map[string]any:
		names := make([]string, 0, len(typed))
		for name := range typed {
			names = append(names, name)
		}
		sort.Strings(names)
		fields := make([]string, 0, len(names))
		for _, name := range names {
			rendered, err := readonlyJSONType(typed[name])
			if err != nil {
				return "", fmt.Errorf("JSON property %q: %w", name, err)
			}
			fields = append(fields, "readonly "+quoteTS(name)+": "+rendered)
		}
		return "{ " + strings.Join(fields, "; ") + " }", nil
	case []any:
		items := make([]string, 0, len(typed))
		for index, item := range typed {
			rendered, err := readonlyJSONType(item)
			if err != nil {
				return "", fmt.Errorf("JSON item %d: %w", index, err)
			}
			items = append(items, rendered)
		}
		return "readonly [" + strings.Join(items, ", ") + "]", nil
	default:
		data, err := json.Marshal(value)
		if err != nil {
			return "", fmt.Errorf("marshal JSON literal type: %w", err)
		}
		return string(data), nil
	}
}

package typescript

import (
	"reflect"
	"strings"
	"testing"

	sdkgen "openapi-sdkgen/internal/compiler"
	"openapi-sdkgen/internal/compiler/ir"
)

func TestRequestInputSectionRejectsUnknownSuffix(t *testing.T) {
	operationName := operationTypeName("GET /widgets")
	if _, err := requestInputSection(operationName, operationName+"UnsupportedInput"); err == nil || !strings.Contains(err.Error(), "supported request section suffix") {
		t.Fatalf("requestInputSection error = %v, want unsupported suffix diagnostic", err)
	}
}

func TestOptionalInputCallsEmitOptionsOnlyOverloads(t *testing.T) {
	document, err := sdkgen.Compile([]byte(`{
  "openapi": "3.1.0",
  "info": {"title": "Optional calls", "version": "1"},
  "paths": {
    "/optional": {"get": {"operationId": "optional", "parameters": [{"name": "force", "in": "query", "schema": {"type": "boolean"}}], "responses": {"204": {"description": "OK"}}}},
    "/required": {"post": {"operationId": "required", "requestBody": {"required": true, "content": {"application/json": {"schema": {"type": "string"}}}}, "responses": {"204": {"description": "OK"}}}},
    "/health": {"get": {"operationId": "health", "responses": {"204": {"description": "OK"}}}},
    "/accounts/{accountID}/phone": {"delete": {"operationId": "deletePhone", "parameters": [{"name": "accountID", "in": "path", "required": true, "schema": {"type": "string"}}, {"name": "force", "in": "query", "schema": {"type": "boolean"}}], "responses": {"204": {"description": "OK"}}}}
  }
}`))
	if err != nil {
		t.Fatal(err)
	}
	artifacts, err := SourceArtifacts(document)
	if err != nil {
		t.Fatal(err)
	}
	interfaceBody := func(route, name string) string {
		t.Helper()
		client := ""
		for _, artifact := range artifacts {
			if strings.Contains(string(artifact.Data), "export type RouteKey = "+quoteTS(route)) {
				client = string(artifact.Data)
				break
			}
		}
		start := strings.Index(client, "interface "+name)
		if start < 0 {
			t.Fatalf("missing interface %s:\n%s", name, client)
		}
		end := strings.Index(client[start:], "\n}\n\n")
		if end < 0 {
			t.Fatalf("unterminated interface %s:\n%s", name, client[start:])
		}
		return client[start : start+end]
	}

	optionalName := operationTypeName("GET /optional")
	optionalCall := interfaceBody("GET /optional", optionalName+"Call")
	for _, expected := range []string{
		`(options?: RouteOptions<"GET /optional">)`,
		`(input?: RouteInput<"GET /optional">, options?: RouteOptions<"GET /optional">)`,
		`readonly raw: OperationRawCall<"GET /optional">`,
	} {
		if !strings.Contains(optionalCall, expected) {
			t.Fatalf("optional call missing %q:\n%s", expected, optionalCall)
		}
	}
	optionalRawCall := interfaceBody("GET /optional", optionalName+"RawCall")
	for _, expected := range []string{
		`(options?: RouteOptions<"GET /optional">)`,
		`(input?: RouteInput<"GET /optional">, options?: RouteOptions<"GET /optional">)`,
	} {
		if !strings.Contains(optionalRawCall, expected) {
			t.Fatalf("optional raw call missing %q:\n%s", expected, optionalRawCall)
		}
	}

	requiredName := operationTypeName("POST /required")
	if requiredCall := interfaceBody("POST /required", requiredName+"Call"); strings.Contains(requiredCall, `(options?: RouteOptions<"POST /required">)`) {
		t.Fatalf("required call gained options-only overload:\n%s", requiredCall)
	}
	if requiredRawCall := interfaceBody("POST /required", requiredName+"RawCall"); strings.Contains(requiredRawCall, `(options?: RouteOptions<"POST /required">)`) {
		t.Fatalf("required raw call gained options-only overload:\n%s", requiredRawCall)
	}

	healthName := operationTypeName("GET /health")
	healthCall := interfaceBody("GET /health", healthName+"Call")
	healthRawCall := interfaceBody("GET /health", healthName+"RawCall")
	if strings.Count(healthCall, `
  (options?: RouteOptions<"GET /health">)`) != 1 || strings.Count(healthRawCall, `
  (options?: RouteOptions<"GET /health">)`) != 1 {
		t.Fatalf("no-input call should retain one options-only signature:\n%s", healthCall)
	}

	deleteName := operationTypeName("DELETE /accounts/{accountID}/phone")
	deleteCall := interfaceBody("DELETE /accounts/{accountID}/phone", deleteName+"Call")
	if strings.Contains(deleteCall, `(options?: RouteOptions<"DELETE /accounts/{accountID}/phone">)`) {
		t.Fatalf("full path call gained options-only overload:\n%s", deleteCall)
	}
	deleteResourceCall := interfaceBody("DELETE /accounts/{accountID}/phone", deleteName+"ResourceCall")
	deleteResourceRawCall := interfaceBody("DELETE /accounts/{accountID}/phone", deleteName+"ResourceRawCall")
	if !strings.Contains(deleteResourceCall, `(options?: RouteOptions<"DELETE /accounts/{accountID}/phone">)`) || !strings.Contains(deleteResourceRawCall, `(options?: RouteOptions<"DELETE /accounts/{accountID}/phone">)`) {
		t.Fatalf("optional resource call missing options-only overload:\n%s", deleteResourceCall)
	}
}

func TestJSDocTypeReferenceFlattensInlineObjectComments(t *testing.T) {
	value := jsDocTypeReference("{\n  /** property docs */\n  readonly id: string\n}")
	if strings.Contains(value, "/*") || value != "`{ readonly id: string }`" {
		t.Fatalf("reference = %q", value)
	}
}

func TestOperationServerURLPrefersOperationThenPathOverride(t *testing.T) {
	document := &ir.Document{Raw: map[string]any{"servers": []any{map[string]any{"url": "https://api.example.test/v1"}}}}
	operation := ir.Operation{
		Path:        "/widgets",
		Method:      "GET",
		Raw:         map[string]any{"servers": []any{map[string]any{"url": "https://operations.example.test/v2"}}},
		PathItemRaw: map[string]any{"servers": []any{map[string]any{"url": "https://paths.example.test/v3"}}},
	}
	if value := operationServers(document, operation); !strings.Contains(value, "operations.example.test/v2") || !strings.Contains(value, `#/paths/~1widgets/get/servers/0`) {
		t.Fatalf("operation servers = %q", value)
	}
	delete(operation.Raw, "servers")
	if value := operationServers(document, operation); !strings.Contains(value, "paths.example.test/v3") || !strings.Contains(value, `#/paths/~1widgets/servers/0`) {
		t.Fatalf("path servers = %q", value)
	}
	operation.PathItemRaw = map[string]any{}
	if value := operationServers(document, operation); !strings.Contains(value, "api.example.test/v1") || !strings.Contains(value, `#/servers/0`) {
		t.Fatalf("root servers = %q", value)
	}
}

func TestRequestBodyTypeRepresentsEmptyTextJSONAndMultiMediaBodies(t *testing.T) {
	for _, test := range []struct {
		name string
		body map[string]any
		want string
	}{
		{name: "empty", body: map[string]any{}, want: "unknown"},
		{name: "text", body: map[string]any{"content": map[string]any{"text/plain": map[string]any{"schema": map[string]any{"type": "object"}}}}, want: "string"},
		{name: "json", body: map[string]any{"content": map[string]any{"application/json": map[string]any{"schema": map[string]any{"type": "integer"}}}}, want: "number"},
		{name: "false binary", body: map[string]any{"content": map[string]any{"application/octet-stream": map[string]any{"schema": false}}}, want: "never"},
		{name: "false binary variant", body: map[string]any{"content": map[string]any{
			"application/json":         map[string]any{"schema": map[string]any{"type": "string"}},
			"application/octet-stream": map[string]any{"schema": false},
		}}, want: `{ readonly contentType: "application/json"; readonly value: string } | { readonly contentType: "application/octet-stream"; readonly value: never }`},
		{name: "multi", body: map[string]any{"content": map[string]any{
			"application/json":         map[string]any{"schema": map[string]any{"type": "string"}},
			"application/octet-stream": map[string]any{"schema": map[string]any{"type": "string", "format": "binary"}},
			"text/plain":               map[string]any{"schema": map[string]any{"type": "string"}},
		}}, want: `{ readonly contentType: "application/json"; readonly value: string } | { readonly contentType: "application/octet-stream"; readonly value: BinaryBody } | { readonly contentType: "text/plain"; readonly value: string }`},
	} {
		t.Run(test.name, func(t *testing.T) {
			value, err := requestBodyType(&ir.Document{}, test.body)
			if err != nil || value != test.want {
				t.Fatalf("requestBodyType = %q, %v; want %q", value, err, test.want)
			}
		})
	}
}

func TestOperationResponseMediaTypesIncludesDefaultResponses(t *testing.T) {
	document := &ir.Document{}
	operation := ir.Operation{Raw: map[string]any{"responses": map[string]any{
		"default": map[string]any{"content": map[string]any{"application/json": map[string]any{}, "text/plain": map[string]any{}}},
	}}}
	mediaTypes, err := operationResponseMediaTypes(document, operation)
	if err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(mediaTypes, []string{"application/json", "text/plain"}) {
		t.Fatalf("media types = %#v", mediaTypes)
	}
}

package typescript

import (
	"bytes"
	"encoding/json"
	"fmt"
	"sort"
	"strings"

	"openapi-sdkgen/internal/compiler/ir"
)

func emitWireComponents(output *bytes.Buffer, document *ir.Document, name string, direction projection) error {
	all := make(map[string]bool, len(document.ComponentSchemas)+len(document.Schemas))
	for schemaName := range document.ComponentSchemas {
		all[schemaName] = true
	}
	for schemaName := range document.Schemas {
		all[schemaName] = true
	}
	names := make([]string, 0, len(all))
	for schemaName := range all {
		names = append(names, schemaName)
	}
	sort.Strings(names)
	properties := make([]runtimeProperty, 0, len(names))
	for _, schemaName := range names {
		value := any(document.ComponentSchemas[schemaName])
		if schema, ok := document.Schemas[schemaName]; ok {
			value = schema.Value
		}
		descriptor, err := wireSchemaDescriptorForDocument(document, value, direction)
		if err != nil {
			return fmt.Errorf("component %s wire schema: %w", schemaName, err)
		}
		properties = append(properties, runtimeProperty{key: schemaName, value: descriptor})
	}
	fmt.Fprintf(output, "const %s: WireSchemas = %s\n\n", name, runtimeObjectExpression(properties))
	return nil
}

func wireSchemaDescriptor(value any, direction projection) (string, error) {
	return wireSchemaDescriptorScoped(value, direction, schemaRequiresFormatAssertion(value), false, wirePropertiesConstructed)
}

func wireSchemaDescriptorForDocument(document *ir.Document, value any, direction projection) (string, error) {
	legacyNullable := document != nil && document.OpenAPIVersionLine == "3.0"
	return wireSchemaDescriptorScoped(value, direction, schemaRequiresFormatAssertion(value), legacyNullable, wirePropertiesConstructed)
}

type wirePropertiesMode uint8

const (
	wirePropertiesConstructed wirePropertiesMode = iota
	wirePropertiesLiteral
)

func wireSchemaDescriptorLiteralForDocument(document *ir.Document, value any, direction projection) (string, error) {
	legacyNullable := document != nil && document.OpenAPIVersionLine == "3.0"
	return wireSchemaDescriptorScoped(value, direction, schemaRequiresFormatAssertion(value), legacyNullable, wirePropertiesLiteral)
}

const formatAssertionVocabulary = "https://json-schema.org/draft/2020-12/vocab/format-assertion"

// schemaRequiresFormatAssertion recognizes the standard assertion vocabulary.
// The OpenAPI base dialect enables format annotation only, so a normal `format`
// remains documentation unless a schema resource explicitly requires this URI.
func schemaRequiresFormatAssertion(value any) bool {
	schema, ok := value.(map[string]any)
	if !ok {
		return false
	}
	vocabularies, _ := schema["$vocabulary"].(map[string]any)
	required, _ := vocabularies[formatAssertionVocabulary].(bool)
	return required
}

func wireSchemaDescriptorScoped(value any, direction projection, formatAssertion, legacyNullable bool, propertyMode wirePropertiesMode) (string, error) {
	if boolean, ok := value.(bool); ok {
		return fmt.Sprintf("{ boolean: %t }", boolean), nil
	}
	schema, ok := value.(map[string]any)
	if !ok {
		return "{}", nil
	}
	if len(schema) == 0 {
		return "{}", nil
	}
	if dynamicReference, ok := schema["x-sdkgen-dynamic-reference"].(map[string]any); ok {
		anchor, _ := dynamicReference["anchor"].(string)
		reference, _ := dynamicReference["reference"].(string)
		name, err := componentSchemaReferenceName(reference)
		if err != nil || anchor == "" {
			if err == nil {
				err = fmt.Errorf("dynamic reference has no anchor")
			}
			return "", err
		}
		referenceDescriptor := "{ dynamicReference: { anchor: " + quoteTS(anchor) + ", fallback: { reference: " + quoteTS(name) + " } } }"
		if len(schema) == 1 {
			return referenceDescriptor, nil
		}
		siblings := make(map[string]any, len(schema)-1)
		for key, value := range schema {
			if key != "x-sdkgen-dynamic-reference" {
				siblings[key] = value
			}
		}
		siblingDescriptor, err := wireSchemaDescriptorScoped(siblings, direction, formatAssertion, legacyNullable, propertyMode)
		if err != nil {
			return "", err
		}
		return mergeWireSchemaDescriptors(referenceDescriptor, siblingDescriptor), nil
	}
	if reference, _ := schema["$ref"].(string); reference != "" {
		name, err := componentSchemaReferenceName(reference)
		if err != nil {
			return "", err
		}
		referenceDescriptor := "{ reference: " + quoteTS(name) + " }"
		if len(schema) == 1 {
			return referenceDescriptor, nil
		}
		siblings := make(map[string]any, len(schema)-1)
		for key, value := range schema {
			if key != "$ref" {
				siblings[key] = value
			}
		}
		siblingDescriptor, err := wireSchemaDescriptorScoped(siblings, direction, formatAssertion, legacyNullable, propertyMode)
		if err != nil {
			return "", err
		}
		return mergeWireSchemaDescriptors(referenceDescriptor, siblingDescriptor), nil
	}

	var fields []string
	if anchor, _ := schema["x-sdkgen-dynamic-anchor"].(string); anchor != "" {
		fields = append(fields, "dynamicAnchor: "+quoteTS(anchor))
	}
	types := schemaTypes(schema["type"])
	if nullable, _ := schema["nullable"].(bool); legacyNullable && nullable && len(types) > 0 {
		hasNull := false
		for _, value := range types {
			hasNull = hasNull || value == "null"
		}
		if !hasNull {
			types = append(types, "null")
		}
	}
	if len(types) > 0 {
		values := make([]string, 0, len(types))
		for _, value := range types {
			values = append(values, quoteTS(value))
		}
		fields = append(fields, "types: ["+strings.Join(values, ", ")+"]")
	}
	if value, exists := schema["const"]; exists {
		encoded, err := runtimeJSONExpression(value)
		if err != nil {
			return "", fmt.Errorf("encode const: %w", err)
		}
		fields = append(fields, "constValue: "+encoded)
	}
	if values, ok := schema["enum"].([]any); ok && len(values) > 0 {
		encoded, err := runtimeJSONExpression(values)
		if err != nil {
			return "", fmt.Errorf("encode enum: %w", err)
		}
		fields = append(fields, "enumValues: "+encoded)
	}
	exclusiveMaximum, maximumIsExclusive := schema["exclusiveMaximum"].(bool)
	exclusiveMinimum, minimumIsExclusive := schema["exclusiveMinimum"].(bool)
	if maximumIsExclusive && exclusiveMaximum {
		if maximum, exists := schema["maximum"]; exists {
			encoded, err := json.Marshal(maximum)
			if err != nil {
				return "", fmt.Errorf("encode maximum: %w", err)
			}
			if len(encoded) > 0 && encoded[0] != '"' {
				fields = append(fields, "exclusiveMaximum: "+string(encoded))
			}
		}
	}
	if minimumIsExclusive && exclusiveMinimum {
		if minimum, exists := schema["minimum"]; exists {
			encoded, err := json.Marshal(minimum)
			if err != nil {
				return "", fmt.Errorf("encode minimum: %w", err)
			}
			if len(encoded) > 0 && encoded[0] != '"' {
				fields = append(fields, "exclusiveMinimum: "+string(encoded))
			}
		}
	}
	for _, keyword := range []string{"multipleOf", "maximum", "exclusiveMaximum", "minimum", "exclusiveMinimum", "minLength", "maxLength", "minItems", "maxItems", "minProperties", "maxProperties"} {
		if (keyword == "maximum" && maximumIsExclusive && exclusiveMaximum) || (keyword == "minimum" && minimumIsExclusive && exclusiveMinimum) || (keyword == "exclusiveMaximum" && maximumIsExclusive) || (keyword == "exclusiveMinimum" && minimumIsExclusive) {
			continue
		}
		value, exists := schema[keyword]
		if !exists {
			continue
		}
		encoded, err := json.Marshal(value)
		if err != nil {
			return "", fmt.Errorf("encode %s: %w", keyword, err)
		}
		if string(encoded) != "true" && string(encoded) != "false" && string(encoded) != "null" && len(encoded) > 0 && encoded[0] != '"' {
			fields = append(fields, keyword+": "+string(encoded))
		}
	}
	if value, ok := schema["pattern"].(string); ok {
		fields = append(fields, "pattern: "+quoteTS(value))
	}
	if value, ok := schema["format"].(string); ok && value != "" {
		fields = append(fields, "format: "+quoteTS(value))
		if formatAssertion || schemaRequiresFormatAssertion(schema) {
			fields = append(fields, "formatAssertion: true")
		}
	}
	if value, ok := schema["uniqueItems"].(bool); ok && value {
		fields = append(fields, "uniqueItems: true")
	}
	if value, ok := schema["contentEncoding"].(string); ok && value != "" {
		fields = append(fields, "contentEncoding: "+quoteTS(value))
	}
	if value, ok := schema["contentMediaType"].(string); ok && value != "" {
		fields = append(fields, "contentMediaType: "+quoteTS(value))
	}
	if value, exists := schema["contentSchema"]; exists {
		descriptor, err := wireSchemaDescriptorScoped(value, direction, formatAssertion, legacyNullable, propertyMode)
		if err != nil {
			return "", err
		}
		fields = append(fields, "contentSchema: "+descriptor)
	}
	if xml, ok := schema["xml"].(map[string]any); ok && len(xml) > 0 {
		encoded, err := runtimeJSONExpression(xml)
		if err != nil {
