func responseWireHeaders(document *ir.Document, response map[string]any) (string, error) {
	headers, _ := response["headers"].(map[string]any)
	if len(headers) == 0 {
		return "", nil
	}
	names := sortedAnyKeys(headers)
	entries := make([]string, 0, len(names))
	for _, name := range names {
		header, _ := headers[name].(map[string]any)
		header, err := resolveComponentObject(document, header, "headers")
		if err != nil {
			return "", err
		}
		schema, contentType, err := responseHeaderSchema(document, header)
		if err != nil {
			return "", err
		}
		descriptor, err := wireSchemaDescriptorForDocument(document, schema, projectionOutput)
		if err != nil {
			return "", err
		}
		style, _ := header["style"].(string)
		if style == "" {
			style = "simple"
		}
		explode, hasExplode := header["explode"].(bool)
		if !hasExplode {
			explode = style == "form"
		}
		entry := "{ name: " + quoteTS(name) + ", property: " + quoteTS(name) + ", style: " + quoteTS(style) + ", explode: " + fmt.Sprint(explode) + ", schema: " + descriptor
		if contentType != "" {
			entry += ", contentType: " + quoteTS(contentType)
		}
		if boolValue(header, "required") {
			entry += ", required: true"
		}
		entries = append(entries, entry+" }")
	}
	return "[" + strings.Join(entries, ", ") + "]", nil
}

func wirePropertyEntriesExpression(properties []runtimeProperty) string {
	var output strings.Builder
	output.WriteString("/* @__PURE__ */ __sdkgen_Properties([")
	for index, property := range properties {
		if index > 0 {
			output.WriteString(", ")
		}
		output.WriteString(quoteTS(property.key))
	}
	output.WriteString("], [")
	for index, property := range properties {
		if index > 0 {
			output.WriteString(", ")
		}
		output.WriteString(property.value)
	}
	output.WriteString("])")
	return output.String()
}

func wirePropertyLiteralExpression(properties []runtimeProperty) string {
	var output strings.Builder
	output.WriteString("/* @__PURE__ */ Object.fromEntries<WireProperty>([")
	for index, property := range properties {
		if index > 0 {
			output.WriteString(", ")
		}
		output.WriteString("[")
		output.WriteString(quoteTS(property.key))
		output.WriteString(", { property: ")
		output.WriteString(quoteTS(property.key))
		output.WriteString(", schema: ")
		output.WriteString(property.value)
		output.WriteString(" }]")
	}
	output.WriteString("])")
	return output.String()
}

