func readRuntimeTemplate(name string) ([]byte, error) {
	source, err := runtimeTemplates.ReadFile("runtime/internal/" + name)
	if err != nil {
		return nil, fmt.Errorf("read TypeScript runtime template %q: %w", name, err)
	}
	return source, nil
}

func emitRuntimeTemplateArtifacts() ([]Artifact, error) {
	artifacts := make([]Artifact, 0, len(runtimeTemplateArtifacts))
	for _, template := range runtimeTemplateArtifacts {
		source, err := readRuntimeTemplate(template.source)
		if err != nil {
			return nil, err
		}
		artifacts = append(artifacts, Artifact{Path: template.path, Data: generatedSource(source)})
	}
	return artifacts, nil
}

// Artifact is a generated TypeScript source file.
type Artifact = generator.Artifact

// Generator emits TypeScript SDK source files from compiler IR.
type Generator struct{}

// Name returns the CLI target name.
func (Generator) Name() string { return "typescript" }

// SupportsAddon reports artifact sets available for TypeScript source output.
func (Generator) SupportsAddon(addon generator.Addon) bool {
	return addon == generator.AddonServer
}

type sourcePlan struct {
	document          *ir.Document
	includeServer     bool
	manifest          *Manifest
	modules           *semanticModulePlan
	links             []generatedLink
	streams           []generatedStream
	webhooks          []webhookDefinition
	callbacks         []callbackDefinition
	resourceTree      *resourceNode
	resourceReachable map[string]bool
}

// Prepare validates author input for the TypeScript target.
func (Generator) Prepare(document *ir.Document, options generator.Options) (generator.Plan, []diagnostic.Diagnostic, error) {
	if document == nil {
		return generator.Plan{}, nil, fmt.Errorf("internal TypeScript target: IR document is nil")
	}
	plan, diagnostics, err := prepareSourcePlan(document, options.HasAddon(generator.AddonServer))
	if err != nil {
		return generator.Plan{}, diagnostics, err
	}
	return generator.NewPlan("typescript", plan), diagnostic.Sort(diagnostics), nil
}

// Emit emits a previously validated TypeScript plan.
func (Generator) Emit(plan generator.Plan) ([]generator.Artifact, error) {
	artifacts := make([]generator.Artifact, 0)
	err := (Generator{}).EmitTo(plan, generator.ArtifactSinkFunc(func(artifact generator.Artifact) error {
		artifacts = append(artifacts, artifact)
		return nil
	}))
	if err != nil {
		return nil, err
	}
	sort.Slice(artifacts, func(i, j int) bool {
		return artifactEmissionOrder(artifacts[i].Path) < artifactEmissionOrder(artifacts[j].Path)
	})
	return artifacts, nil
}

// EmitTo writes each validated source file to the supplied sink as soon as its
// bytes are ready.
func (Generator) EmitTo(plan generator.Plan, sink generator.ArtifactSink) error {
	value, err := plan.Value("typescript")
	if err != nil {
		return fmt.Errorf("internal TypeScript target: %w", err)
	}
	prepared, ok := value.(*sourcePlan)
	if !ok {
		return fmt.Errorf("internal TypeScript target: unexpected plan type %T", value)
	}
	if sink == nil {
		return fmt.Errorf("internal TypeScript target: artifact sink is nil")
	}
	return emitSourcePlanTo(prepared, sink.WriteArtifact)
}

// Generate is the compatibility convenience for direct target callers.
func (target Generator) Generate(document *ir.Document, options generator.Options) ([]generator.Artifact, error) {
	plan, diagnostics, err := target.Prepare(document, options)
	if err != nil {
		return nil, err
	}
	if diagnostic.HasErrors(diagnostics) {
		return nil, fmt.Errorf("%s", strings.TrimSpace(diagnostic.RenderHuman(diagnostics, nil)))
	}
	return target.Emit(plan)
}

type Manifest struct {
	Operations []ManifestOperation `json:"operations"`
}

type ManifestOperation struct {
	RouteKey           string   `json:"routeKey"`
	OperationID        string   `json:"operationID"`
	Summary            string   `json:"summary,omitempty"`
	Description        string   `json:"description,omitempty"`
	Method             string   `json:"method"`
	Path               string   `json:"path"`
	CallExpression     string   `json:"callExpression"`
	ResourceSegments   []string `json:"resourceSegments"`
	PathParameterOrder []string `json:"pathParameterOrder"`
	InputTypes         []string `json:"inputTypes"`
	OutputType         string   `json:"outputType"`
	ErrorType          string   `json:"errorType"`
	Envelope           string   `json:"envelope,omitempty"`
	Pagination         string   `json:"pagination,omitempty"`
	Auth               string   `json:"auth"`
	Visibility         string   `json:"visibility"`
	Deprecated         bool     `json:"deprecated"`
	outputExpression   typeExpression
	errorExpression    typeExpression
	rawResponse        typeExpression
	mediaOutputs       map[string]typeExpression
	renderedMedia      map[string]string
	mediaTypes         []string
	streamMediaTypes   []string
	security           []operationSecurityRequirement
	hasSecurity        bool
	optionsRequired    bool
	paginationRequest  ir.PaginationRequestPlan
	compiled           ir.Operation
	prepared           preparedOperation
}

const generatedFileHeader = `// cspell:disable
/** @noprettier -- generated by openapi-sdkgen */
// <auto-generated />
// @generated by openapi-sdkgen
// Code generated by openapi-sdkgen. DO NOT EDIT.
// This file is generated. Do not edit, lint, or format it manually.
// @ts-nocheck
/* eslint-disable */
/* oxlint-disable */
/* biome-ignore-all lint: generated file */
/* deno-lint-ignore-file */
// dprint-ignore-file

`

// SourceArtifacts emits TypeScript source that a consumer compiles as part of
// its own application. It deliberately contains no package metadata or build
// configuration.
func SourceArtifacts(document *ir.Document) ([]Artifact, error) {
	return sourceArtifacts(document, false)
}

func sourceArtifacts(document *ir.Document, includeServer bool) ([]Artifact, error) {
	plan, diagnostics, err := prepareSourcePlan(document, includeServer)
	if err != nil {
		return nil, err
	}
	if diagnostic.HasErrors(diagnostics) {
		return nil, fmt.Errorf("%s", strings.TrimSpace(diagnostic.RenderHuman(diagnostics, nil)))
	}
	return emitSourcePlan(plan)
}

func prepareSourcePlan(document *ir.Document, includeServer bool) (*sourcePlan, []diagnostic.Diagnostic, error) {
	if document == nil {
		return nil, nil, fmt.Errorf("IR document is nil")
	}
	prepared, diagnostics, err := prepareKnownExtensions(document)
	if err != nil {
		return nil, nil, err
	}
	plan := &sourcePlan{document: prepared, includeServer: includeServer}
	targetDiagnostics := prepareTargetDiagnostics(plan)
	diagnostics = append(diagnostics, targetDiagnostics...)
	manifest, manifestErrors := buildManifestDiagnostics(prepared)
	for _, manifestErr := range manifestErrors {
		diagnostics = append(diagnostics, loweringPreparationDiagnostic(prepared, manifestErr))
	}
	helperManifest := manifest
	if len(manifestErrors) != 0 {
		helperManifest = visibilityManifest(prepared)
	} else {
		plan.manifest = &manifest
	}
	links, linkErrors := generatedLinksDiagnostics(prepared, helperManifest)
	for _, linksErr := range linkErrors {
		diagnostics = append(diagnostics, helperPreparationDiagnostic(prepared, "response links", "SDKGEN-E509", linksErr))
	}
	if len(linkErrors) == 0 {
		plan.links = links
	}
	streams, streamErrors := generatedStreamsDiagnostics(prepared, helperManifest)
	for _, streamsErr := range streamErrors {
		diagnostics = append(diagnostics, helperPreparationDiagnostic(prepared, "response streams", "SDKGEN-E510", streamsErr))
	}
	if len(streamErrors) == 0 {
		plan.streams = streams
	}
	if len(manifestErrors) == 0 && len(linkErrors) == 0 && len(streamErrors) == 0 {
		if plan.manifest != nil {
			tree, reachable, reconcileErr := reconcileResourceCapabilities(prepared, &manifest, links, streams)
			if reconcileErr != nil {
				diagnostics = append(diagnostics, loweringPreparationDiagnostic(prepared, reconcileErr))
			} else {
				plan.resourceTree = tree
				plan.resourceReachable = reachable
			}
			plan.manifest = &manifest
		}
	}
	if includeServer {
		webhooks, webhookErrors := collectWebhooksDiagnostics(prepared)
		for _, webhookErr := range webhookErrors {
			diagnostics = append(diagnostics, serverPreparationDiagnostic(prepared, "webhook contracts", webhookErr))
		}
		if len(webhookErrors) == 0 {
			plan.webhooks = webhooks
		}
		callbacks, callbackErrors := collectCallbacksDiagnostics(prepared)
		for _, callbackErr := range callbackErrors {
			diagnostics = append(diagnostics, serverPreparationDiagnostic(prepared, "callback contracts", callbackErr))
		}
		if len(callbackErrors) == 0 {
			plan.callbacks = callbacks
		}
	}
	if plan.manifest != nil && !diagnostic.HasErrors(diagnostics) {
		modules, moduleErr := buildSemanticModulePlan(prepared, *plan.manifest, plan.resourceTree, includeServer)
		if moduleErr != nil {
			return nil, diagnostic.Sort(diagnostics), fmt.Errorf("build TypeScript semantic module plan: %w", moduleErr)
		}
		plan.modules = modules
	}
	return plan, diagnostic.Sort(diagnostics), nil
}

func reconcileResourceCapabilities(document *ir.Document, manifest *Manifest, links []generatedLink, streams []generatedStream) (*resourceNode, map[string]bool, error) {
	tree, err := buildResourceTree(document, *manifest, resourceCapabilityMembers(links, streams))
	if err != nil {
		return nil, nil, err
	}
	reachable := make(map[string]bool)
	resourceOperationIDs(tree, reachable)
	for index := range manifest.Operations {
		item := &manifest.Operations[index]
		if item.Visibility != "public" || reachable[item.RouteKey] {
			continue
		}
		operation := item.compiled
		item.CallExpression = exactOperationCall(document, operation, item.InputTypes)
		item.ResourceSegments = nil
	}
	return tree, reachable, nil
}

func emitSourcePlan(plan *sourcePlan) ([]Artifact, error) {
	artifacts := make([]Artifact, 0)
	if err := emitSourcePlanTo(plan, func(artifact Artifact) error {
		artifacts = append(artifacts, artifact)
		return nil
	}); err != nil {
		return nil, err
	}
	sort.Slice(artifacts, func(i, j int) bool {
		return artifactEmissionOrder(artifacts[i].Path) < artifactEmissionOrder(artifacts[j].Path)
	})
	return artifacts, nil
}

func emitSourcePlanTo(plan *sourcePlan, sink func(Artifact) error) error {
	document := plan.document
	includeServer := plan.includeServer
	if plan.manifest == nil {
		return fmt.Errorf("internal TypeScript target: prepared plan has no manifest")
	}
	manifest := *plan.manifest
	write := validatedArtifactWriter(sink)
	typesSource, err := emitSchemaArtifactsTo(document, plan.modules, write)
	if err != nil {
		return err
	}
	if err := emitOperationArtifactsTo(document, manifest, plan.modules, plan.resourceTree, plan.resourceReachable, plan.links, plan.streams, write); err != nil {
		return err
	}
	if err := emitRouteArtifactsTo(manifest, plan.modules, write); err != nil {
		return err
	}
	registrySource, err := emitClientRegistry(document, manifest, plan.modules, plan.links, plan.streams)
	if err != nil {
		return err
	}
	if err := write(Artifact{Path: plan.modules.fixed["client-registry"], Data: generatedSource(registrySource)}); err != nil {
		return err
	}
	constantsSource, err := readRuntimeTemplate("constants.ts")
	if err != nil {
		return err
	}
	enumsSource, err := emitEnums(document)
	if err != nil {
		return err
	}
	errorsSource, err := emitErrors(document)
	if err != nil {
		return err
	}
	metadataSource, err := emitMetadata(document, true)
	if err != nil {
		return err
	}
	if err := emitResourceArtifactsTo(document, plan.modules, plan.resourceTree, write); err != nil {
		return err
	}
	clientIndexSource, err := emitClientArtifactsTo(document, manifest, plan.modules, plan.links, plan.streams, write)
	if err != nil {
		return err
	}
	if err := validateSourceExportSymbols(map[string][]byte{
		"client":    clientIndexSource,
		"constants": constantsSource,
		"enums":     enumsSource,
		"errors":    errorsSource,
		"metadata":  metadataSource,
		"types":     typesSource,
	}); err != nil {
		return err
	}
	indexSource := generatedIndexSource(enumsSource)
	runtimeArtifacts, err := emitRuntimeTemplateArtifacts()
	if err != nil {
		return err
	}
	for _, artifact := range []Artifact{
		{Path: "index.ts", Data: generatedSource([]byte("export * from \"./internal/index.js\"\n"))},
		{Path: "internal/enums.ts", Data: generatedSource(enumsSource)},
		{Path: "internal/errors.ts", Data: generatedSource(errorsSource)},
		{Path: "internal/index.ts", Data: generatedSource(indexSource)},
		{Path: "enums.ts", Data: generatedSource([]byte("export * from \"./internal/enums.js\"\n"))},
		{Path: "metadata.ts", Data: generatedSource(metadataSource)},
	} {
		if err := write(artifact); err != nil {
			return err
		}
	}
	for _, artifact := range runtimeArtifacts {
		if err := write(artifact); err != nil {
			return err
		}
	}
	if includeServer {
		serverArtifacts, err := emitPreparedServerArtifacts(document, plan.webhooks, plan.callbacks)
		if err != nil {
			return err
		}
		for _, artifact := range serverArtifacts {
			if err := write(artifact); err != nil {
				return err
			}
		}
	}
	return nil
}

func validatedArtifactWriter(sink func(Artifact) error) func(Artifact) error {
	seen := make(map[string]string)
	return func(artifact Artifact) error {
		if err := validateArtifactPath(artifact.Path); err != nil {
			return fmt.Errorf("generated artifact %q: %w", artifact.Path, err)
		}
		key := portableArtifactPathKey(artifact.Path)
		if previous, exists := seen[key]; exists {
			return fmt.Errorf("generated artifact %q collides with %q", artifact.Path, previous)
		}
		seen[key] = artifact.Path
		if !bytes.HasPrefix(artifact.Data, []byte(generatedFileHeader)) {
			return fmt.Errorf("generated artifact %q is missing the standard header", artifact.Path)
		}
		return sink(artifact)
	}
}

func artifactEmissionOrder(path string) string {
	if strings.HasPrefix(path, "internal/") {
		return "0/" + path
	}
	switch path {
	case "index.ts":
		return "1/" + path
	case "enums.ts":
		return "2/" + path
	case "metadata.ts":
		return "3/" + path
	default:
		return "4/" + path
	}
}

func generatedIndexSource(enumsSource []byte) []byte {
	var output strings.Builder
	output.WriteString("export type * from \"./schemas/index.js\"\n")
	output.WriteString("export type { BothPaginationInput, CursorPaginationInput, OffsetPaginationInput } from \"./runtime/pagination.js\"\n")
	for _, module := range []string{"enums", "errors"} {
		fmt.Fprintf(&output, "export type * from %s\n", quoteTS("./"+module+".js"))
	}
	output.WriteString("export type * from \"./routes/index.js\"\n")
	output.WriteString("export type * from \"./routes/helpers.js\"\n")
	output.WriteString("export type * from \"./client/index.js\"\n")
	output.Write(publicRuntimeExportSource())
	output.WriteString("export { SortDirection } from \"./runtime/constants.js\"\n")
	if exportedSymbols(string(enumsSource))["isEnumValue"] {
		output.WriteString("export { Enums, isEnumValue } from \"./enums.js\"\n")
	} else {
		output.WriteString("export { Enums } from \"./enums.js\"\n")
	}
	output.WriteString("export { isErrorCategory } from \"./errors.js\"\n")
	output.WriteString("export { createClient } from \"./client/index.js\"\n")
	output.WriteString("export { APIError, TransportErrorCode, getErrorCode, getRequestID, isAPIError, isErrorCode } from \"./runtime/errors.js\"\n")
	return []byte(output.String())
}

func generatedSource(source []byte) []byte {
	result := make([]byte, len(generatedFileHeader)+len(source))
	copy(result, generatedFileHeader)
	copy(result[len(generatedFileHeader):], source)
	return result
}

func validateSourceExportSymbols(modules map[string][]byte) error {
	owners := make(map[string]string)
	moduleNames := make([]string, 0, len(modules))
	for module := range modules {
		moduleNames = append(moduleNames, module)
	}
	sort.Strings(moduleNames)
	for _, module := range moduleNames {
		exports := exportedSymbols(string(modules[module]))
		for symbol := range exports {
			if previous, exists := owners[symbol]; exists && previous != module {
				return fmt.Errorf("generated source export %q is declared by both %s and %s modules", symbol, previous, module)
			}
			owners[symbol] = module
		}
	}
	return nil
}

func exportedSymbols(source string) map[string]bool {
	result := make(map[string]bool)
	inExportBlock := false
	for _, line := range strings.Split(source, "\n") {
		trimmed := strings.TrimSpace(line)
		if inExportBlock {
			if trimmed == "}" {
				inExportBlock = false
				continue
			}
			name := strings.TrimSuffix(trimmed, ",")
			if before, after, found := strings.Cut(name, " as "); found {
				_ = before
				name = after
			}
			if name != "" {
				result[name] = true
			}
			continue
		}
		if !strings.HasPrefix(trimmed, "export ") {
			continue
		}
		rest := strings.TrimSpace(strings.TrimPrefix(trimmed, "export "))
		if rest == "{" || rest == "type {" {
			inExportBlock = true
			continue
		}
		if strings.HasPrefix(rest, "{") || strings.HasPrefix(rest, "type {") {
			open := strings.Index(rest, "{")
			close := strings.Index(rest, "}")
			if open >= 0 && close > open {
				for _, name := range strings.Split(rest[open+1:close], ",") {
					name = strings.TrimSpace(name)
					if before, after, found := strings.Cut(name, " as "); found {
						_ = before
						name = after
					}
					if name != "" {
						result[name] = true
					}
				}
			}
			continue
		}
		fields := strings.Fields(rest)
		if len(fields) < 2 {
			continue
		}
		switch fields[0] {
		case "type", "interface", "const", "function", "class":
			result[strings.Split(fields[1], "<")[0]] = true
		}
	}
	return result
}

func buildManifest(document *ir.Document) (Manifest, error) {
	manifest, failures := buildManifestDiagnostics(document)
	if len(failures) != 0 {
		return Manifest{}, failures[0]
	}
	return manifest, nil
}

func buildManifestDiagnostics(document *ir.Document) (Manifest, []error) {
	manifest := Manifest{
		Operations: make([]ManifestOperation, 0, len(document.Operations)),
	}
	_, errorsBySchema, failures := errorContractsDiagnostics(document)
	for _, operation := range document.Operations {
		operationFailed := false
		prepared, prepareErr := prepareOperation(document, operation)
		if prepareErr != nil {
			failures = append(failures, fmt.Errorf("operation %s parameters: %w", operationLabel(operation), prepareErr))
			operationFailed = true
		}
		outputExpression, err := operationOutputTypeExpression(document, operation)
		if err != nil {
			failures = append(failures, fmt.Errorf("operation %s output: %w", operationLabel(operation), err))
			operationFailed = true
		}
		inputTypes, inputErr := operationInputTypesFromPrepared(document, operation, prepared)
		if inputErr != nil {
			failures = append(failures, fmt.Errorf("operation %s input: %w", operationLabel(operation), inputErr))
			operationFailed = true
		}
		errorExpression, err := operationErrorTypeExpression(document, operation, errorsBySchema)
		if err != nil {
			failures = append(failures, fmt.Errorf("operation %s error: %w", operationLabel(operation), err))
			operationFailed = true
		}
		rawResponse, err := operationRawResponseTypeExpression(document, operation)
		if err != nil {
			failures = append(failures, fmt.Errorf("operation %s raw response: %w", operationLabel(operation), err))
			operationFailed = true
		}
		mediaOutputs, err := operationMediaOutputTypeExpressions(document, operation)
		if err != nil {
			failures = append(failures, fmt.Errorf("operation %s media outputs: %w", operationLabel(operation), err))
			operationFailed = true
		}
		renderedMedia := renderMediaOutputTypes(mediaOutputs, typeRenderContract)
		mediaTypes := make([]string, 0, len(renderedMedia))
		for mediaType := range renderedMedia {
			mediaTypes = append(mediaTypes, mediaType)
		}
		sort.Strings(mediaTypes)
		streamMediaTypes, err := operationStreamingResponseMediaTypes(document, operation)
		if err != nil {
			failures = append(failures, fmt.Errorf("operation %s stream media: %w", operationLabel(operation), err))
			operationFailed = true
		}
		security, hasSecurity, err := operationSecurityRequirements(document, operation)
		if err != nil {
			failures = append(failures, fmt.Errorf("operation %s security: %w", operationLabel(operation), err))
			operationFailed = true
		}
		callExpression := ""
		var segments []string
		if inputErr == nil {
			var callErr error
			callExpression, segments, callErr = operationCallFromPrepared(document, operation, inputTypes, prepared)
			if callErr != nil {
				failures = append(failures, fmt.Errorf("operation %s call expression: %w", operationLabel(operation), callErr))
				operationFailed = true
			}
		}
		if operationFailed {
			continue
		}
		prepared.inputRequired, err = prepared.clientInputRequired(document, operation, inputTypes, false)
		if err != nil {
			failures = append(failures, fmt.Errorf("operation %s input requirement: %w", operationLabel(operation), err))
			continue
		}
		prepared.resourceInputRequired, err = prepared.clientInputRequired(document, operation, inputTypes, true)
		if err != nil {
			failures = append(failures, fmt.Errorf("operation %s resource input requirement: %w", operationLabel(operation), err))
			continue
		}
		visibility := operation.Visibility
		if visibility == "" {
			visibility = "public"
		}
		manifest.Operations = append(manifest.Operations, ManifestOperation{
			RouteKey:           operationRouteKey(operation),
			OperationID:        operation.OperationID,
			Summary:            operation.Summary,
			Description:        operation.Description,
			Method:             operation.Method,
			Path:               operation.Path,
			CallExpression:     callExpression,
			ResourceSegments:   segments,
			PathParameterOrder: append([]string{}, operation.PathParameterOrder...),
			InputTypes:         append([]string{}, inputTypes...),
			OutputType:         outputExpression.render(typeRenderLocal),
			ErrorType:          errorExpression.render(typeRenderLocal),
			Envelope:           operation.Envelope,
			Pagination:         operation.Pagination,
			Auth:               operationAuth(operation),
			Visibility:         visibility,
			Deprecated:         boolValue(operation.Raw, "deprecated"),
			outputExpression:   outputExpression,
			errorExpression:    errorExpression,
			rawResponse:        rawResponse,
			mediaOutputs:       mediaOutputs,
			renderedMedia:      renderedMedia,
			mediaTypes:         mediaTypes,
			streamMediaTypes:   streamMediaTypes,
			security:           security,
			hasSecurity:        hasSecurity,
			optionsRequired:    len(security) > 1,
			paginationRequest: func() ir.PaginationRequestPlan {
				if operation.PaginationPlan == nil {
					return ir.PaginationRequestPlan{}
				}
				return operation.PaginationPlan.Request
			}(),
			compiled: operation,
			prepared: prepared,
		})
	}
	if len(failures) != 0 {
		return manifest, failures
	}
	tree, err := buildResourceTree(document, manifest)
	if err != nil {
		return Manifest{}, append(failures, err)
	}
	reachable := make(map[string]bool)
	resourceOperationIDs(tree, reachable)
	for index := range manifest.Operations {
		item := &manifest.Operations[index]
		if item.Visibility == "public" && !reachable[item.RouteKey] {
			operation := item.compiled
			item.CallExpression = exactOperationCall(document, operation, item.InputTypes)
			item.ResourceSegments = nil
		}
	}
	return manifest, failures
}

func visibilityManifest(document *ir.Document) Manifest {
	result := Manifest{Operations: make([]ManifestOperation, 0, len(document.Operations))}
	for _, operation := range document.Operations {
		visibility := operation.Visibility
		if visibility == "" {
			visibility = "public"
		}
		result.Operations = append(result.Operations, ManifestOperation{
			RouteKey:    operationRouteKey(operation),
			OperationID: operation.OperationID,
			Method:      operation.Method,
			Path:        operation.Path,
			Visibility:  visibility,
			compiled:    operation,
		})
	}
	return result
}

func (operation ManifestOperation) renderOutput(scope typeRenderScope) string {
	if operation.outputExpression.local == "" && operation.outputExpression.contract == "" {
		return operation.OutputType
	}
	return operation.outputExpression.render(scope)
}

func (operation ManifestOperation) renderError(scope typeRenderScope) string {
	if operation.errorExpression.local == "" && operation.errorExpression.contract == "" {
		return operation.ErrorType
	}
	return operation.errorExpression.render(scope)
}

func operationCall(document *ir.Document, operation ir.Operation, inputTypes []string) (string, []string, error) {
	prepared, err := prepareOperation(document, operation)
	if err != nil {
		return "", nil, err
	}
	return operationCallFromPrepared(document, operation, inputTypes, prepared)
}

func operationCallFromPrepared(document *ir.Document, operation ir.Operation, inputTypes []string, prepared preparedOperation) (string, []string, error) {
	if hasDuplicateStrings(operation.PathParameterOrder) {
		return exactOperationCall(document, operation, inputTypes), nil, nil
	}
	pathBindings := prepared.pathBindings
	parts := resourcePathParts(operation.Path)
	segments := make([]string, 0, len(parts))
	chain := "api"
	for _, part := range parts {
		name, parameterPart, supported := resourcePathPart(part)
		if !supported {
			return exactOperationCall(document, operation, inputTypes), nil, nil
		}
		if parameterPart {
			binding := pathBindings[name]
			if binding == "" {
				return exactOperationCall(document, operation, inputTypes), nil, nil
			}
			chain += "(" + binding + ")"
			continue
		}
		property, err := naming.Property(part)
		if err != nil {
			return exactOperationCall(document, operation, inputTypes), nil, nil
		}
		segments = append(segments, property)
		chain += "." + property
	}
	terminal, err := resourceTerminalName(operation, parts)
	if err != nil {
		return exactOperationCall(document, operation, inputTypes), nil, nil
	}
	if operation.Visibility == "internal" {
		return exactOperationCall(document, operation, inputTypes), segments, nil
	}
	return chain + "." + terminal + callInput(operation, inputTypes, len(operation.PathParameterOrder) > 0, operation.PathParameterOrder, pathBindings), segments, nil
}

func exactOperationCall(document *ir.Document, operation ir.Operation, inputTypes []string) string {
	pathBindings, _ := operationPathBindings(document, operation)
	if operation.OperationID != "" {
		return "api.$operations[" + quoteTS(operation.OperationID) + "]" + callInput(operation, inputTypes, false, operation.PathParameterOrder, pathBindings)
	}
	return "api.$routes[" + quoteTS(operationRouteKey(operation)) + "]" + callInput(operation, inputTypes, false, operation.PathParameterOrder, pathBindings)
}

func resourcePathParts(path string) []string {
	trimmed := strings.Trim(path, "/")
	if trimmed == "" {
		return nil
	}
	return strings.Split(trimmed, "/")
}

func resourcePathPart(part string) (string, bool, bool) {
	if !strings.ContainsAny(part, "{}") {
		return part, false, true
	}
	if strings.HasPrefix(part, "{") && strings.HasSuffix(part, "}") &&
		strings.Count(part, "{") == 1 && strings.Count(part, "}") == 1 && len(part) > 2 {
		return strings.TrimSuffix(strings.TrimPrefix(part, "{"), "}"), true, true
	}
	return "", false, false
}

func hasDuplicateStrings(values []string) bool {
	seen := make(map[string]bool, len(values))
	for _, value := range values {
		if seen[value] {
			return true
		}
		seen[value] = true
	}
	return false
}

// resourceTerminalName keeps literal path segments as namespaces. For example,
// POST /auth/login becomes api.auth.login.post(), rather than api.auth.login().
func resourceTerminalName(operation ir.Operation, parts []string) (string, error) {
	terminal, err := terminalName(operation, parts)
	if err != nil {
		return "", err
	}
	if len(parts) == 0 {
		return terminal, nil
	}
	last := parts[len(parts)-1]
	if strings.HasPrefix(last, "{") {
		return terminal, nil
	}
	property, err := naming.Property(last)
	if err != nil {
		return "", err
	}
	if terminal != property {
		return terminal, nil
	}
	return methodTerminal(operation.Method)
}

func methodTerminal(method string) (string, error) {
	switch method {
	case "GET":
		return "get", nil
	case "POST":
		return "post", nil
	case "PUT":
		return "replace", nil
	case "PATCH":
		return "patch", nil
	case "DELETE":
		return "delete", nil
	case "QUERY":
		return "query", nil
	default:
		return naming.Property(strings.ToLower(method))
	}
}

func operationPathBindings(document *ir.Document, operation ir.Operation) (map[string]string, error) {
	parameters, err := operationParameters(document, operation)
	if err != nil {
		return nil, err
	}
	result := make(map[string]string)
	for _, parameter := range parameters {
		if parameter.Location == "path" {
			result[parameter.Name] = parameter.Binding
		}
	}
	return result, nil
}

func callInput(operation ir.Operation, inputTypes []string, pathBound bool, pathParameters []string, pathBindings map[string]string) string {
	var fields []string
	for _, inputType := range inputTypes {
		switch {
		case strings.HasSuffix(inputType, "PathInput"):
			if pathBound {
				continue
			}
			values := make([]string, 0, len(pathParameters))
			seen := make(map[string]bool, len(pathParameters))
			for _, parameter := range pathParameters {
				if seen[parameter] {
					continue
				}
				seen[parameter] = true
				binding := pathBindings[parameter]
				if binding == "" {
					binding = stablePrivateIdentifier("example-path-parameter", parameter)
				}
				values = append(values, quoteTS(parameter)+": "+binding)
			}
			fields = append(fields, "path: { "+strings.Join(values, ", ")+" }")
		case strings.HasSuffix(inputType, "QueryInput"):
			fields = append(fields, "query")
		case strings.HasSuffix(inputType, "QuerystringInput"):
			fields = append(fields, "querystring")
		case strings.HasSuffix(inputType, "HeaderInput"):
			fields = append(fields, "headerParams")
		case strings.HasSuffix(inputType, "CookieInput"):
			fields = append(fields, "cookieParams")
		case strings.HasSuffix(inputType, "BodyInput"):
			fields = append(fields, "body")
		}
	}
	var arguments []string
	if len(fields) > 0 {
		arguments = append(arguments, "{ "+strings.Join(fields, ", ")+" }")
	}
	return "(" + strings.Join(arguments, ", ") + ")"
}

func terminalName(operation ir.Operation, parts []string) (string, error) {
	last := ""
	if len(parts) > 0 {
		last = parts[len(parts)-1]
	}
	if isTerminalAction(operation, parts, len(parts)-1) {
		return naming.Property(last)
	}
	lowerID := strings.ToLower(operation.OperationID)
	switch operation.Method {
	case "GET":
		if strings.HasPrefix(lowerID, "list") || strings.HasPrefix(lowerID, "search") {
			return "list", nil
		}
		return "get", nil
	case "POST":
		if strings.HasPrefix(lowerID, "create") {
			return "create", nil
		}
		return "post", nil
	case "PUT":
		return "replace", nil
	case "PATCH":
		return "patch", nil
	case "DELETE":
		return "delete", nil
	case "QUERY":
		return "query", nil
	default:
		return naming.Property(strings.ToLower(operation.Method))
	}
}

func isTerminalAction(operation ir.Operation, parts []string, index int) bool {
	if index < 0 || index != len(parts)-1 || operation.Method == "GET" || len(parts) < 2 {
		return false
	}
	last := parts[index]
	if last == "" || strings.HasPrefix(last, "{") {
		return false
	}
	return strings.Contains(operation.OperationID, strings.ToUpper(last[:1])+last[1:]) || !strings.HasPrefix(strings.ToLower(operation.OperationID), "create")
}

func operationTypeName(operationID string) string {
	return stablePrivateIdentifier("operation-type", operationID)
}

func operationAuth(operation ir.Operation) string {
	if operation.Parameters != nil {
		if !operation.SecurityDeclared {
			return "inherited"
		}
		if len(operation.Security) == 0 {
			return "public"
		}
		return "required"
	}
	security, exists := operation.Raw["security"]
	if !exists {
		return "inherited"
	}
	items, _ := security.([]any)
	if len(items) == 0 {
		return "public"
	}
	return "required"
}

func boolValue(values map[string]any, key string) bool {
	value, _ := values[key].(bool)
	return value
}

package typescript

import (
	"bytes"
	pathpkg "path"
	"regexp"
	"sort"
	"strings"
	"testing"

	"openapi-sdkgen/internal/compiler"
	"openapi-sdkgen/internal/compiler/ir"
)

var runtimeImportPattern = regexp.MustCompile(`\bfrom\s+["']([^"']+)["']`)

func TestRuntimeModulesAreInvariantOwnedAndAcyclic(t *testing.T) {
	firstDocument, err := sdkgen.Compile([]byte(emitterFixture))
	if err != nil {
		t.Fatal(err)
	}
	secondDocument, err := sdkgen.Compile([]byte(`{
  "openapi": "3.1.1",
  "info": {"title": "Unrelated runtime fixture", "version": "1"},
  "paths": {
    "/health": {
      "head": {
        "responses": {"204": {"description": "healthy"}}
      }
    }
  }
}`))
	if err != nil {
		t.Fatal(err)
	}

	first := generatedRuntimeArtifactMap(t, firstDocument)
	second := generatedRuntimeArtifactMap(t, secondDocument)
	expected := []string{
		"internal/runtime/callables.ts",
		"internal/runtime/codecs.ts",
		"internal/runtime/configuration.ts",
		"internal/runtime/constants.ts",
		"internal/runtime/errors.ts",
		"internal/runtime/http.ts",
		"internal/runtime/identity.ts",
		"internal/runtime/links.ts",
		"internal/runtime/objects.ts",
		"internal/runtime/operation.ts",
		"internal/runtime/pagination.ts",
		"internal/runtime/request.ts",
		"internal/runtime/security.ts",
		"internal/runtime/streaming.ts",
		"internal/runtime/transport.ts",
		"internal/runtime/wire-properties.ts",
	}
	if paths := sortedRuntimePaths(first); strings.Join(paths, "\n") != strings.Join(expected, "\n") {
		t.Fatalf("runtime artifact paths = %v, want %v", paths, expected)
	}
	if paths := sortedRuntimePaths(second); strings.Join(paths, "\n") != strings.Join(expected, "\n") {
		t.Fatalf("unrelated runtime artifact paths = %v, want %v", paths, expected)
	}
	for _, artifactPath := range expected {
		if !bytes.Equal(first[artifactPath], second[artifactPath]) {
			t.Fatalf("runtime artifact %s varies across unrelated documents", artifactPath)
		}
	}

	owners := make(map[string]string)
	graph := make(map[string][]string, len(first))
	for artifactPath, source := range first {
		for symbol := range exportedSymbols(string(source)) {
			if previous, exists := owners[symbol]; exists {
				t.Fatalf("runtime export %q is owned by both %s and %s", symbol, previous, artifactPath)
			}
			owners[symbol] = artifactPath
		}
		for _, match := range runtimeImportPattern.FindAllSubmatch(source, -1) {
			specifier := string(match[1])
			if !strings.HasPrefix(specifier, "./") {
				t.Fatalf("runtime artifact %s imports non-runtime owner %q", artifactPath, specifier)
			}
			target := pathpkg.Clean(pathpkg.Join(pathpkg.Dir(artifactPath), strings.TrimSuffix(specifier, ".js")+".ts"))
			if _, exists := first[target]; !exists {
				t.Fatalf("runtime artifact %s imports unowned runtime module %q", artifactPath, target)
			}
			graph[artifactPath] = append(graph[artifactPath], target)
		}
	}
	assertAcyclicRuntimeGraph(t, graph)
}

func generatedRuntimeArtifactMap(t *testing.T, document *ir.Document) map[string][]byte {
	t.Helper()
	artifacts, err := SourceArtifacts(document)
	if err != nil {
		t.Fatal(err)
	}
	result := make(map[string][]byte)
	for _, artifact := range artifacts {
		if strings.HasPrefix(artifact.Path, "internal/runtime/") {
			result[artifact.Path] = artifact.Data
		}
		if artifact.Path == "internal/runtime.ts" || artifact.Path == "internal/constants.ts" {
			t.Fatalf("legacy runtime artifact remains: %s", artifact.Path)
		}
		if (strings.HasPrefix(artifact.Path, "internal/client/") || artifact.Path == "internal/errors.ts") && strings.Contains(string(artifact.Data), `from "./runtime.js"`) {
			t.Fatalf("legacy runtime import remains in %s", artifact.Path)
		}
	}
	return result
}

func sortedRuntimePaths(artifacts map[string][]byte) []string {
	result := make([]string, 0, len(artifacts))
	for artifactPath := range artifacts {
		result = append(result, artifactPath)
	}
	sort.Strings(result)
	return result
}

func assertAcyclicRuntimeGraph(t *testing.T, graph map[string][]string) {
	t.Helper()
	state := make(map[string]uint8, len(graph))
	var visit func(string)
	visit = func(node string) {
		switch state[node] {
		case 1:
			t.Fatalf("runtime import graph contains a cycle at %s", node)
		case 2:
			return
		}
		state[node] = 1
		for _, target := range graph[node] {
			visit(target)
		}
		state[node] = 2
	}
	for node := range graph {
		visit(node)
	}
}

import { isRecord } from "./objects.js";
import type { OperationDefinition } from "./operation.js";
import type { OperationStream, RawResponse, RequestOptions } from "./request.js";

/** Low-level request executor used by generated operation bindings. */
export interface RequestFunction {
  /**
   * Sends an operation and returns its decoded response body.
   *
   * @param operation Generated operation metadata.
   * @param input Generated path, query, header, cookie, and body input.
   * @param options Per-request transport options.
   */
  <Output>(
    operation: OperationDefinition,
    input?: unknown,
    options?: RequestOptions,
  ): Promise<Output>;
  /**
   * Sends an operation and returns its decoded body with HTTP response metadata.
   *
   * @param operation Generated operation metadata.
   * @param input Generated path, query, header, cookie, and body input.
   * @param options Per-request transport options.
   */
  raw<Output>(
    operation: OperationDefinition,
    input?: unknown,
    options?: RequestOptions,
  ): Promise<RawResponse<Output>>;
  /** Opens one declared streaming response and lazily decodes its items. */
  stream<Item>(
    operation: OperationDefinition,
    input?: unknown,
    options?: RequestOptions,
  ): OperationStream<Item>;
}

type RequiredKeys<Value> = {
  [Key in keyof Value]-?: Record<never, never> extends Pick<Value, Key> ? never : Key;
}[keyof Value];

type OperationOptionsArguments<Options extends RequestOptions> = [RequiredKeys<Options>] extends [
  never,
]
  ? [options?: Options]
  : [options: Options];

const generatedOperationInputKeys = [
  "body",
  "path",
  "query",
  "querystring",
  "headerParams",
  "cookieParams",
] as const;

function isGeneratedOperationInput(value: unknown): boolean {
  return isRecord(value) && generatedOperationInputKeys.some((key) => Object.hasOwn(value, key));
}

function splitOptionalOperationArguments<Input, Options extends RequestOptions>(
  args: readonly unknown[],
): readonly [Input | undefined, Options | undefined] {
  const [first, second] = args;
  if (args.length > 1 || isGeneratedOperationInput(first)) {
    return [first as Input | undefined, second as Options | undefined];
  }
  return [undefined, first as Options | undefined];
}

function operationOptionsArguments<Options extends RequestOptions>(
  options: Options | undefined,
): OperationOptionsArguments<Options> {
  return (options === undefined ? [] : [options]) as OperationOptionsArguments<Options>;
}

/** Callable generated operation that requires typed input. */
export interface InputOperationCall<Input, Output, Options extends RequestOptions, Raw> {
  /** Sends the request and returns the decoded response body. */
  (input: Input, ...options: OperationOptionsArguments<Options>): Promise<Output>;
  /** Sends the request and returns decoded data with HTTP response metadata. */
  raw(input: Input, ...options: OperationOptionsArguments<Options>): Promise<Raw>;
}

/** Callable generated operation with no input object. */
export interface NoInputOperationCall<Output, Options extends RequestOptions, Raw> {
  /** Sends the request and returns the decoded response body. */
  (...options: OperationOptionsArguments<Options>): Promise<Output>;
  /** Sends the request and returns decoded data with HTTP response metadata. */
  raw(...options: OperationOptionsArguments<Options>): Promise<Raw>;
}

/**
 * Callable operation surface selected from whether the operation accepts input.
 *
 * Generated clients specialize this type with operation-specific input, output,
 * options, and raw-response types.
 */
export type OperationCall<
  Input,
  Output,
  Options extends RequestOptions = RequestOptions,
  Raw = RawResponse<Output>,
> = [Input] extends [never]
  ? NoInputOperationCall<Output, Options, Raw>
  : InputOperationCall<Input, Output, Options, Raw>;

/**
 * Binds generated operation metadata to a low-level request executor.
 *
 * Used by generated clients; applications normally call the generated operation instead.
 */
export function bindOperation<
  Input,
  Output,
  Options extends RequestOptions = RequestOptions,
  Raw = RawResponse<Output>,
>(
  request: RequestFunction,
  operation: OperationDefinition,
  hasInput: boolean,
  inputOptional = false,
): OperationCall<Input, Output, Options, Raw> {
  const call = hasInput
    ? inputOptional
      ? (...args: readonly unknown[]) => {
          const [input, options] = splitOptionalOperationArguments<Input, Options>(args);
          return request<Output>(operation, input, options);
        }
      : (input: Input, ...options: OperationOptionsArguments<Options>) =>
          request<Output>(operation, input, options[0])
    : (...options: OperationOptionsArguments<Options>) =>
        request<Output>(operation, undefined, options[0]);
  const raw = hasInput
    ? inputOptional
      ? (...args: readonly unknown[]) => {
          const [input, options] = splitOptionalOperationArguments<Input, Options>(args);
          return request.raw<Output>(operation, input, options);
        }
      : (input: Input, ...options: OperationOptionsArguments<Options>) =>
          request.raw<Output>(operation, input, options[0])
    : (...options: OperationOptionsArguments<Options>) =>
        request.raw<Output>(operation, undefined, options[0]);
  return Object.assign(call, { raw }) as OperationCall<Input, Output, Options, Raw>;
}

/** Binds generated streaming operation metadata with the same input and options dispatch as decoded calls. */
export function bindStreamOperation<Input, Item, Options extends RequestOptions = RequestOptions>(
  request: RequestFunction,
  operation: OperationDefinition,
  hasInput: boolean,
  inputOptional = false,
  defaultAccept?: string,
): (...args: readonly unknown[]) => OperationStream<Item> {
  const streamOptions = (options: Options | undefined): Options | undefined => {
    if (defaultAccept === undefined || options?.accept !== undefined) return options;
    return { ...options, accept: defaultAccept } as Options;
  };
  return (...args: readonly unknown[]) => {
    if (!hasInput)
      return request.stream<Item>(
        operation,
        undefined,
        streamOptions(args[0] as Options | undefined),
      );
    if (!inputOptional)
      return request.stream<Item>(
        operation,
        args[0] as Input,
        streamOptions(args[1] as Options | undefined),
      );
    const [input, options] = splitOptionalOperationArguments<Input, Options>(args);
    return request.stream<Item>(operation, input, streamOptions(options));
  };
}

/**
 * Binds resource path parameters to an input operation.
 *
 * Used to implement generated instance builders such as `api.products(productID)`.
 */
export function bindPathOperation<
  FullInput,
  Input,
  Output,
  Options extends RequestOptions = RequestOptions,
  Raw = RawResponse<Output>,
>(
  operation: Pick<InputOperationCall<FullInput, Output, Options, Raw>, "raw">,
  path: Readonly<Record<string, unknown>>,
  hasInput: boolean,
  inputOptional = false,
): OperationCall<Input, Output, Options, Raw> {
  // Generated exact calls remain callable at runtime even when their public
  // decoded-call signature is intentionally hidden (for example, an operation
  // with no successful buffered response). Resource binding only requires the
  // public raw capability at its boundary, then restores that generated runtime invariant.
  const callable = operation as InputOperationCall<FullInput, Output, Options, Raw>;
  const mergeInput = (input: Input | undefined): FullInput =>
    ({
      ...(isRecord(input) ? input : {}),
      path,
    }) as FullInput;
  const call = hasInput
    ? inputOptional
      ? (...args: readonly unknown[]) => {
          const [input, options] = splitOptionalOperationArguments<Input, Options>(args);
          return callable(mergeInput(input), ...operationOptionsArguments(options));
        }
      : (input: Input, ...options: OperationOptionsArguments<Options>) =>
          callable(mergeInput(input), ...options)
    : (...options: OperationOptionsArguments<Options>) =>
        callable(mergeInput(undefined), ...options);
  const raw = hasInput
    ? inputOptional
      ? (...args: readonly unknown[]) => {
          const [input, options] = splitOptionalOperationArguments<Input, Options>(args);
          return callable.raw(mergeInput(input), ...operationOptionsArguments(options));
        }
      : (input: Input, ...options: OperationOptionsArguments<Options>) =>
          callable.raw(mergeInput(input), ...options)
    : (...options: OperationOptionsArguments<Options>) =>
        callable.raw(mergeInput(undefined), ...options);
  const sourceStream = (
    callable as InputOperationCall<FullInput, Output, Options, Raw> & {
      readonly stream?: (...args: readonly unknown[]) => unknown;
    }
  ).stream;
  const stream =
    sourceStream === undefined
      ? undefined
      : hasInput
        ? inputOptional
          ? (...args: readonly unknown[]) => {
              const [input, options] = splitOptionalOperationArguments<Input, Options>(args);
              return sourceStream(mergeInput(input), options);
            }
          : (input: Input, ...options: OperationOptionsArguments<Options>) =>
              sourceStream(mergeInput(input), options[0])
        : (...options: OperationOptionsArguments<Options>) =>
            sourceStream(mergeInput(undefined), options[0]);
  return Object.assign(call, { raw }, stream === undefined ? {} : { stream }) as OperationCall<
    Input,
    Output,
    Options,
    Raw
  >;
}

/** Adds namespace members to a callable without colliding with Function prototype properties. */
export function assignCallableProperties<
  Call extends (...args: never[]) => unknown,
  Members extends object,
>(call: Call, members: Members): Call & Members {
  for (const [key, value] of Object.entries(members)) {
    Object.defineProperty(call, key, {
      value,
      enumerable: true,
      configurable: true,
      writable: true,
    });
  }
  return call as Call & Members;
}

/** Reuses the existing operation import edge for the shared wire-property constructor. */
export { wireProperties as createWireProperties } from "./wire-properties.js";

import type { WireProperty, WireSchema } from "./codecs.js";

/** Constructs exact identity-mapped property wrappers without changing schema ownership. */
export function wireProperties(
  keys: readonly string[], schemas: readonly WireSchema[],
): Readonly<Record<string, WireProperty>> {
  if (keys.length !== schemas.length) throw new TypeError("wire property entry count mismatch");
  const entries: [string, WireProperty][] = new Array(keys.length);
  for (let i = 0; i < keys.length; i++) {
    const property = keys[i]!;
    entries[i] = [property, { property, schema: schemas[i]! }];
  }
  return Object.fromEntries(entries);
}
